请对以下 case 进行三维加权评分。

=== case_id ===
Case-01-low-power-014

=== 用户原始指令 (query.txt) ===
出差总忘记提前充电，上次飞机上手机没电差点误事。帮我做低电管理卡，上方大区域显示电量和"距离下次会议还有3小时"倒计时感信息，下面纵向排列今天日程每条前面勾选框双向绑定可勾选，底部按钮跳系统省电设置，深色舞台配夜晚渐变，5%以下红色超限告警纯文字色块。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "出差总忘记提前充电，上次飞机上手机没电差点误事。帮我做低电管理卡，上方大区域显示电量和\"距离下次会议还有3小时\"倒计时感信息，下面纵向排列今天日程每条前面勾选框双向绑定可勾选，底部按钮跳系统省电设置，深色舞台配夜晚渐变，5%以下红色超限告警纯文字色块。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "battery"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "device": {
        "batteryPercent": {
          "type": "integer",
          "description": "当前手机电量百分比，用于低电管理主数值展示。",
          "sampleValue": 4
        },
        "batteryText": {
          "type": "string",
          "description": "当前手机电量的展示文本。",
          "sampleValue": "4%"
        },
        "batteryStatusText": {
          "type": "string",
          "description": "当前电量状态提示，5%以下展示超限告警。",
          "sampleValue": "低于5% 超限告警"
        },
        "batteryStatusColor": {
          "type": "string",
          "description": "电量状态文字色，5%以下使用告警红色。",
          "sampleValue": "#ffdb6b42"
        },
        "batteryAlertBgColor": {
          "type": "string",
          "description": "电量告警文字色块背景色，5%以下使用低透明红色。",
          "sampleValue": "#ffdb6b42"
        },
        "batteryProgressColor": {
          "type": "string",
          "description": "电量进度条颜色，低电时使用告警色。",
          "sampleValue": "#ffdb6b42"
        },
        "progressTotal": {
          "type": "integer",
          "description": "电量进度条总量。",
          "sampleValue": 100
        }
      },
      "meeting": {
        "countdownText": {
          "type": "string",
          "description": "距离下次会议的倒计时展示文本。",
          "sampleValue": "距离下次会议还有3小时"
        }
      },
      "calendar": {
        "items": {
          "type": "array",
          "description": "今天日程列表。",
          "sampleValue": [
            {
              "entityName": "calendar",
              "entityId": "event-001",
              "title": "客户同步会",
              "dtStart": "14:00",
              "dtEnd": "15:00",
              "checked": false
            },
            {
              "entityName": "calendar",
              "entityId": "event-002",
              "title": "登机前确认",
              "dtStart": "17:30",
              "dtEnd": "17:50",
              "checked": true
            }
          ],
          "items": {
            "type": "object",
            "description": "日程项。",
            "sampleValue": {
              "entityName": "calendar",
              "entityId": "event-001",
              "title": "客户同步会",
              "dtStart": "14:00",
              "dtEnd": "15:00",
              "checked": false
            },
            "properties": {
              "entityName": {
                "type": "string",
                "description": "内容类别。",
                "sampleValue": "calendar"
              },
              "entityId": {
                "type": "string",
                "description": "日程唯一标识。",
                "sampleValue": "event-001"
              },
              "title": {
                "type": "string",
                "description": "日程标题。",
                "sampleValue": "客户同步会"
              },
              "dtStart": {
                "type": "string",
                "description": "日程开始时间。",
                "sampleValue": "14:00"
              },
              "dtEnd": {
                "type": "string",
                "description": "日程结束时间。",
                "sampleValue": "15:00"
              },
              "checked": {
                "type": "boolean",
                "description": "日程前置复选框选中状态。",
                "sampleValue": false
              }
            }
          }
        }
      }
    },
    "ui": {
      "title": {
        "type": "string",
        "description": "卡片标题。",
        "sampleValue": "低电管理"
      },
      "scheduleTitle": {
        "type": "string",
        "description": "日程分组标题。",
        "sampleValue": "今日日程"
      },
      "actionLabel": {
        "type": "string",
        "description": "底部跳转按钮文案。",
        "sampleValue": "省电设置"
      }
    }
  },
  "assetCandidates": []
}

